CREATE OR REPLACE FUNCTION crm_private.guard_asset()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin
if tg_op='UPDATE' then
 if new.owner_id<>old.owner_id or new.scope<>old.scope then raise exception using errcode='42501',message='Proprietário e escopo são permanentes.'; end if;
 if (new.status is distinct from old.status and new.status='aprovado') or(new.visibility is distinct from old.visibility and new.visibility='public') then if not public.can_manage_operations() then raise exception using errcode='42501',message='A gestão deve aprovar a divulgação.'; end if; end if;
 -- Changing the file of approved material always requires reapproval, including manager uploads.
 if new.current_version_id is distinct from old.current_version_id then new.status:='pendente'; end if;
else if (new.status='aprovado' or new.visibility='public') and not public.can_manage_operations() then raise exception using errcode='42501',message='A gestão deve aprovar a divulgação.'; end if;
end if;
if new.current_version_id is not null and not exists(select 1 from public.asset_versions v where v.id=new.current_version_id and v.asset_id=new.id) then raise exception using errcode='23514',message='Versão inválida.'; end if;
new.updated_at:=now();return new;end $function$

CREATE OR REPLACE FUNCTION public.crm_assign_lead(target_lead bigint, target_broker uuid, assignment_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare previous_broker uuid; lead_name text; begin
  if not public.can_manage_operations() then raise exception 'Acesso negado' using errcode = '42501'; end if;
  if length(trim(coalesce(assignment_reason,''))) not between 1 and 500 then raise exception 'Informe o motivo da atribuicao'; end if;
  if not exists (select 1 from public.brokers b join public.user_roles r on r.id = b.id
    where b.id = target_broker and r.disabled_at is null and r.role in ('admin','manager','broker','corretor')) then
    raise exception 'Corretor invalido ou inativo';
  end if;
  select broker_id, name into previous_broker, lead_name from public.leads where id = target_lead for update;
  if not found then raise exception 'Lead nao encontrado'; end if;
  if previous_broker is not distinct from target_broker then return; end if;
  update public.leads set broker_id = target_broker, assigned_at = now() where id = target_lead;
  insert into public.lead_assignments(lead_id, previous_broker_id, broker_id, assigned_by, reason)
    values(target_lead, previous_broker, target_broker, auth.uid(), trim(assignment_reason));
  insert into public.lead_activities(lead_id,user_id,type,description)
    values(target_lead,auth.uid(),'lead_assigned',trim(assignment_reason));
  insert into public.notifications(user_id,title,description,type)
    values(target_broker,'Novo lead atribuido',lead_name,'lead_atribuido');
  update public.tasks set deleted_at = now(), updated_at = now() where lead_id = target_lead and broker_id = previous_broker and status <> 'concluida';
  insert into public.tasks(title,broker_id,lead_id,due_at)
    values('Primeiro contato: ' || left(coalesce(lead_name, 'Cliente'),120),target_broker,target_lead,now());
end $function$

CREATE OR REPLACE FUNCTION public.crm_confirm_presentation_share(target_share bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.marketing_shares; inserted_id bigint;
begin
 if not public.can_manage_commercial() then raise exception using errcode='42501',message='Sessão comercial necessária.';end if;
 select * into s from public.marketing_shares where id=target_share and(owner_id=auth.uid() or public.can_manage_operations());
 if s.id is null then raise exception using errcode='42501',message='Apresentação não autorizada.';end if;
 if s.lead_id is not null and not exists(select 1 from public.leads l where l.id=s.lead_id and(l.broker_id=auth.uid() or public.can_manage_operations())) then raise exception using errcode='42501',message='Lead não autorizado.';end if;
 insert into public.crm_event_log(owner_id,event_type,entity_id,idempotency_key) values(auth.uid(),'presentation_shared',s.id,'share-confirmed:'||s.id) on conflict(idempotency_key) do nothing returning id into inserted_id;
 if inserted_id is not null and s.lead_id is not null then insert into public.lead_activities(lead_id,user_id,type,description) values(s.lead_id,auth.uid(),'note','Envio confirmado pelo corretor: '||s.title||' · canal '||s.channel||' · link /apresentacoes/'||s.token::text);end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.crm_protect_property_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if auth.uid() is not null and not public.can_manage_operations() then
  if tg_op='INSERT' then
   if new.approved_by is not null or new.approved_at is not null then
    raise exception 'Somente a gestao pode aprovar imoveis.' using errcode='42501';
   end if;
   new.workflow_status := 'rascunho';
   new.publish_on_site := false;
   new.submitted_by := auth.uid();
  else
   if new.approved_by is distinct from old.approved_by
      or new.approved_at is distinct from old.approved_at
      or (new.workflow_status is distinct from old.workflow_status
          and new.workflow_status not in ('rascunho','pendente')) then
    raise exception 'Somente a gestao pode aprovar imoveis.' using errcode='42501';
   end if;
   if new.publish_on_site and new.workflow_status not in ('aprovado','publicado') then
    raise exception 'Imovel precisa de aprovacao para publicacao.' using errcode='42501';
   end if;
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.crm_record_contact(target_lead bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l public.leads; begin
  if not public.can_manage_commercial() then raise exception 'Acesso negado' using errcode = '42501'; end if;
  select * into l from public.leads where id = target_lead for update;
  if not found or (not public.can_manage_operations() and l.broker_id is distinct from auth.uid()) then
    raise exception 'Lead nao encontrado ou sem permissao' using errcode = '42501';
  end if;
  if l.first_contact_at is not null then return; end if;
  update public.leads set first_contact_at = now(), status = case when status = 'novo' then 'em atendimento' else status end where id = target_lead;
end $function$
